mod functional_preprocess;
use std::ffi::{CStr,CString};
use std::os::raw::c_char;
#[no_mangle]
pub unsafe extern "C" fn review_execute(op:*const c_char,values:*const f64,n:usize,w:usize,parameters:*const f64,k:usize)->*mut c_char{
    let result=std::panic::catch_unwind(||{
        let operation=CStr::from_ptr(op).to_str().unwrap();
        let flat=std::slice::from_raw_parts(values,n*w);
        let rows=flat.chunks_exact(w).map(|r|r.to_vec()).collect::<Vec<_>>();
        let args=std::slice::from_raw_parts(parameters,k);
        functional_preprocess::run(operation,&rows,args)
    });
    CString::new(match result{Ok(Ok(j))=>j,Ok(Err(e))=>format!("{{\"error\":{:?}}}",e),Err(_)=>"{\"error\":\"panic\"}".into()}).unwrap().into_raw()
}
#[no_mangle]
pub unsafe extern "C" fn review_free(p:*mut c_char){drop(CString::from_raw(p));}
